const memberFallback=name=>{const initial=String(name||'?').slice(0,1).replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[character]));return`data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120"><circle cx="60" cy="60" r="56" fill="none" stroke="#ff6384" stroke-width="4"/><text x="60" y="68" text-anchor="middle" font-family="sans-serif" font-size="42" fill="#ff6384">${initial}</text></svg>`)}`};
const memberImage=(name,soopId)=>soopId?`https://stimg.sooplive.com/LOGO/${soopId.slice(0,2).toLowerCase()}/${soopId}/${soopId}.jpg`:memberFallback(name);

window.nyachoToast=(message,type='success')=>{let box=document.querySelector('#toastStack');if(!box){box=document.createElement('div');box.id='toastStack';box.setAttribute('role','status');box.setAttribute('aria-live','polite')}const host=[...document.querySelectorAll('dialog[open]')].pop()||document.body;if(box.parentElement!==host)host.append(box);const item=document.createElement('div');item.className=`toast toast-${type}`;item.textContent=message;box.append(item);requestAnimationFrame(()=>item.classList.add('show'));setTimeout(()=>{item.classList.remove('show');setTimeout(()=>item.remove(),300)},2600)};
function isMemberAdmin(){return document.body.classList.contains('admin-mode')}
function saveMembers(){localStorage.setItem('nyacho-members',JSON.stringify(nyachoMembers))}
function saveMemberGroups(){localStorage.setItem('nyacho-member-groups',JSON.stringify(nyachoMemberGroups));window.nyachoFirebaseSave?.('memberGroups',nyachoMemberGroups)}
async function loadSharedMembers(){const response=await fetch(`${MEMBER_SUPABASE_URL}/rest/v1/members?select=name,type,img,soop_id&order=name.asc`,{headers:{apikey:MEMBER_SUPABASE_KEY}});if(!response.ok)throw new Error(`Supabase 멤버 조회 실패 (${response.status})`);const rows=await response.json();nyachoMembers={};rows.forEach((row,index)=>{if(!row?.name)return;const id=`shared-${index}-${encodeURIComponent(row.name)}`;nyachoMembers[id]={id,name:row.name,type:row.type||'member',img:row.img||memberImage(row.name,row.soop_id||''),soopId:row.soop_id||''}});saveMembers();refreshMemberSuggestions();window.nyachoRenderToday?.();if(memberDialog.open){renderMemberTabs();renderMembers()}}
async function manageSharedMembers(method,payload){const token=await window.nyachoGetFirebaseToken?.();if(!token)throw new Error('Firebase 관리자 로그인을 다시 해주세요.');const response=await fetch(`${MEMBER_SUPABASE_URL}/functions/v1/manage-danz-members`,{method,headers:{apikey:MEMBER_SUPABASE_KEY,Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||result.message||`Supabase 멤버 저장 실패 (${response.status})`);return result}
const upsertSharedMembers=list=>manageSharedMembers('POST',{members:list.map(member=>({name:member.name,type:member.type==='crew'?'crew':'member',img:member.img||'',soop_id:member.soopId||''}))});
const deleteSharedMember=name=>manageSharedMembers('DELETE',{name});
function refreshMemberSuggestions(){document.querySelector('#memberSuggestions')?.remove();document.querySelectorAll('.manage-members').forEach(valueInput=>{valueInput.removeAttribute('list');if(valueInput.dataset.memberAutocomplete)return;valueInput.dataset.memberAutocomplete='true';valueInput.type='hidden';const editor=document.createElement('div'),chips=document.createElement('div'),queryInput=document.createElement('input'),results=document.createElement('div');editor.className='member-chip-editor';chips.className='member-chip-list';queryInput.className='member-chip-query';queryInput.type='text';queryInput.placeholder='멤버 이름을 입력하세요';queryInput.autocomplete='off';results.className='member-autocomplete-results';results.hidden=true;valueInput.after(editor);editor.append(chips,queryInput,results);const values=()=>valueInput.value.split(',').map(name=>name.trim()).filter(Boolean),allItems=()=>[...Object.values(nyachoMemberGroups).map(group=>({name:group.name,kind:'그룹',img:''})),...Object.values(nyachoMembers).map(member=>({name:member.name,kind:'멤버',img:member.img||memberImage(member.name,member.soopId)}))],close=()=>{results.hidden=true;results.innerHTML=''};const renderChips=()=>{chips.innerHTML='';values().forEach(name=>{const chip=document.createElement('span');chip.className='member-chip';chip.innerHTML='<span></span><button type="button" aria-label="멤버 제거">×</button>';chip.querySelector('span').textContent=name;chip.querySelector('button').onclick=()=>{valueInput.value=values().filter(value=>value!==name).join(', ');renderChips();queryInput.focus()};chips.append(chip)})};const addValue=name=>{name=String(name||'').trim();if(!name)return;const current=values();if(!current.some(value=>value.toLowerCase()===name.toLowerCase()))current.push(name);valueInput.value=current.join(', ');queryInput.value='';renderChips();close();queryInput.focus()};const findMatches=()=>{const query=queryInput.value.trim().toLowerCase();if(!query)return[];return allItems().filter(item=>item.name.toLowerCase().includes(query)&&!values().some(value=>value.toLowerCase()===item.name.toLowerCase())).sort((a,b)=>{const aStart=a.name.toLowerCase().startsWith(query),bStart=b.name.toLowerCase().startsWith(query);return Number(bStart)-Number(aStart)||a.name.localeCompare(b.name,'ko')}).slice(0,8)};const showMatches=()=>{results.innerHTML='';if(!queryInput.value.trim()){close();return}const matches=findMatches();if(!matches.length){results.innerHTML='<p>Enter를 누르면 직접 추가됩니다.</p>';results.hidden=false;return}matches.forEach(item=>{const button=document.createElement('button');button.type='button';button.innerHTML='<span class="member-autocomplete-avatar"></span><span class="member-autocomplete-copy"><b></b><small></small></span>';const avatar=button.querySelector('.member-autocomplete-avatar');if(item.img){const image=document.createElement('img');image.src=item.img;image.alt='';avatar.append(image)}else avatar.textContent='●';button.querySelector('b').textContent=item.name;button.querySelector('small').textContent=item.kind;button.onmousedown=event=>event.preventDefault();button.onclick=()=>addValue(item.name);results.append(button)});results.hidden=false};queryInput.addEventListener('input',showMatches);queryInput.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();addValue(findMatches()[0]?.name||queryInput.value)}else if(event.key==='Backspace'&&!queryInput.value&&values().length){event.preventDefault();const current=values();current.pop();valueInput.value=current.join(', ');renderChips()}else if(event.key==='Escape')close()});queryInput.addEventListener('blur',()=>setTimeout(close,120));editor.addEventListener('click',event=>{if(!event.target.closest('.member-chip'))queryInput.focus()});renderChips()})}
function memberListForActiveGroup(){const all=Object.values(nyachoMembers);if(!activeMemberGroup)return all;const names=new Set(nyachoMemberGroups[activeMemberGroup]?.members||[]);return all.filter(member=>names.has(member.name))}
function expandScheduleMembers(value){const result=[],seen=new Set();String(value||'').split(',').map(name=>name.trim()).filter(Boolean).forEach(name=>{const names=nyachoMemberGroups[name]?.members||[name];names.forEach(memberName=>{if(!seen.has(memberName)){seen.add(memberName);result.push(memberName)}})});return result}
window.nyachoMemberNames=value=>expandScheduleMembers(value);
window.nyachoRenderMemberProfiles=(container,value)=>{container.className='detail-member-profiles';expandScheduleMembers(value).forEach(name=>{const member=Object.values(nyachoMembers).find(item=>item.name===name),soopId=String(member?.soopId||'').trim(),card=document.createElement(soopId?'a':'div');card.className='detail-member-profile';if(soopId){card.href=`https://www.sooplive.com/station/${encodeURIComponent(soopId)}`;card.target='_blank';card.rel='noopener noreferrer';card.title=`${name} 방송국`}card.innerHTML='<img alt=""><span></span>';const image=card.querySelector('img');image.src=member?.img||memberImage(name,member?.soopId||'');image.alt=`${name} 프로필`;image.onerror=()=>{image.onerror=null;image.src=memberFallback(name)};card.querySelector('span').textContent=name;container.append(card)})};

function renderMemberTabs(){const groupRows=Object.values(nyachoMemberGroups).sort((a,b)=>a.name.localeCompare(b.name,'ko'));memberTabs.innerHTML='';const all=document.createElement('div');all.className=`member-group-tab-row${activeMemberGroup===null?' active':''}`;all.innerHTML=`<button type="button"><span>전체 멤버</span><small>${Object.keys(nyachoMembers).length}</small></button>`;all.querySelector('button').onclick=()=>{activeMemberGroup=null;renderMemberTabs();renderMembers()};memberTabs.append(all);groupRows.forEach(group=>{const row=document.createElement('div');row.className=`member-group-tab-row${activeMemberGroup===group.name?' active':''}`;row.innerHTML=`<button type="button" class="member-group-select"><span></span><small></small></button><button type="button" class="member-group-edit" aria-label="그룹 수정">✎</button>`;row.querySelector('.member-group-select span').textContent=group.name;row.querySelector('small').textContent=group.members?.length||0;row.querySelector('.member-group-select').onclick=()=>{activeMemberGroup=group.name;renderMemberTabs();renderMembers()};row.querySelector('.member-group-edit').onclick=()=>openMemberGroupEditor(group.name);memberTabs.append(row)})}
function renderMembers(){const query=document.querySelector('#memberSearch').value.trim().toLowerCase(),list=memberListForActiveGroup().filter(member=>!query||member.name.toLowerCase().includes(query)||member.soopId?.toLowerCase().includes(query)).sort((a,b)=>a.name.localeCompare(b.name,'ko'));memberGrid.innerHTML='';if(!list.length){memberGrid.innerHTML='<p class="member-empty">등록된 멤버가 없습니다.</p>';return}list.forEach(member=>{const card=document.createElement('article');card.className='member-card';card.innerHTML='<button type="button" class="member-delete" aria-label="멤버 삭제">×</button><img alt=""><strong></strong><small></small>';const image=card.querySelector('img');image.src=member.img||memberImage(member.name,member.soopId);image.alt=`${member.name} 프로필`;image.onerror=()=>{image.onerror=null;image.src=memberFallback(member.name)};card.querySelector('strong').textContent=member.name;card.querySelector('small').textContent=member.soopId||'SOOP ID 없음';card.querySelector('.member-delete').onclick=()=>deleteMember(member.name);memberGrid.append(card)})}
function openMemberManager(){if(!isMemberAdmin())return;document.querySelector('#profileMenu').hidden=true;activeMemberGroup=null;closeMemberGroupEditor();renderMemberTabs();renderMembers();memberDialog.showModal()}
async function addMember(){const name=document.querySelector('#memberName').value.trim(),soopId=document.querySelector('#memberSoopId').value.trim();if(!name){document.querySelector('#memberName').focus();return}if(Object.values(nyachoMembers).some(member=>member.name.toLowerCase()===name.toLowerCase())){alert('이미 등록된 멤버입니다.');return}try{await upsertSharedMembers([{name,type:'member',soopId,img:memberImage(name,soopId)}]);document.querySelector('#memberName').value='';document.querySelector('#memberSoopId').value='';await loadSharedMembers();window.nyachoToast(`${name} 멤버가 추가되었습니다.`)}catch(error){alert(error.message)}}
async function deleteMember(name){if(!confirm(`[${name}] 멤버를 삭제할까요?`))return;try{await deleteSharedMember(name);Object.values(nyachoMemberGroups).forEach(group=>group.members=(group.members||[]).filter(memberName=>memberName!==name));saveMemberGroups();await loadSharedMembers();renderMemberTabs();window.nyachoToast(`${name} 멤버가 삭제되었습니다.`)}catch(error){alert(error.message)}}

function renderGroupPicker(){const query=document.querySelector('#memberGroupSearch').value.trim().toLowerCase(),list=Object.values(nyachoMembers).filter(member=>!query||member.name.toLowerCase().includes(query)).sort((a,b)=>a.name.localeCompare(b.name,'ko'));const picker=document.querySelector('#memberGroupPicker');picker.innerHTML='';list.forEach(member=>{const selected=selectedGroupMembers.has(member.name),button=document.createElement('button');button.type='button';button.className=`member-picker-option${selected?' selected':''}`;button.innerHTML='<img alt=""><span></span><b></b>';button.querySelector('img').src=member.img||memberFallback(member.name);button.querySelector('span').textContent=member.name;button.querySelector('b').textContent=selected?'✓':'＋';button.onclick=()=>{selected?selectedGroupMembers.delete(member.name):selectedGroupMembers.add(member.name);renderGroupPicker();renderGroupPreview()};picker.append(button)});if(!list.length)picker.innerHTML='<p class="member-empty">검색 결과가 없습니다.</p>'}
function renderGroupPreview(){document.querySelector('#memberGroupPreview').textContent=selectedGroupMembers.size?`선택 ${selectedGroupMembers.size}명 · ${[...selectedGroupMembers].join(', ')}`:'그룹에 포함할 멤버를 선택해주세요.'}
function openMemberGroupEditor(name=''){const group=name?nyachoMemberGroups[name]:null;editingMemberGroup=group?.name||null;selectedGroupMembers=new Set(group?.members||[]);memberDefaultView.hidden=true;memberGroupEditor.hidden=false;document.querySelector('#memberGroupEditorTitle').textContent=group?`${group.name} 수정`:'새 그룹 추가';document.querySelector('#memberGroupName').value=group?.name||'';document.querySelector('#memberGroupSearch').value='';document.querySelector('#memberGroupDelete').hidden=!group;renderGroupPicker();renderGroupPreview();document.querySelector('#memberGroupName').focus()}
function closeMemberGroupEditor(){memberGroupEditor.hidden=true;memberDefaultView.hidden=false;editingMemberGroup=null;selectedGroupMembers.clear()}
function saveGroup(){const name=document.querySelector('#memberGroupName').value.trim();if(!name){document.querySelector('#memberGroupName').focus();return}if(!selectedGroupMembers.size){alert('멤버를 1명 이상 선택해주세요.');return}if(nyachoMemberGroups[name]&&name!==editingMemberGroup){alert('이미 등록된 그룹입니다.');return}if(editingMemberGroup&&editingMemberGroup!==name)delete nyachoMemberGroups[editingMemberGroup];nyachoMemberGroups[name]={name,members:[...selectedGroupMembers]};if(activeMemberGroup===editingMemberGroup)activeMemberGroup=name;saveMemberGroups();refreshMemberSuggestions();renderMemberTabs();renderMembers();closeMemberGroupEditor()}
function deleteGroup(){if(!editingMemberGroup||!confirm(`[${editingMemberGroup}] 그룹을 삭제할까요?`))return;delete nyachoMemberGroups[editingMemberGroup];if(activeMemberGroup===editingMemberGroup)activeMemberGroup=null;saveMemberGroups();refreshMemberSuggestions();renderMemberTabs();renderMembers();closeMemberGroupEditor()}

function exportMemberData(){const payload={format:'nyacho-member-data',version:1,exportedAt:new Date().toISOString(),members:Object.values(nyachoMembers),groups:Object.values(nyachoMemberGroups)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`nyacho-members-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url)}
async function importMemberData(file){
  if(!file)return;
  try{
    const data=JSON.parse(await file.text());
    if(!Array.isArray(data.members)||!Array.isArray(data.groups))throw new Error();
    const newMembers=[];
    data.members.forEach(member=>{
      if(!member?.name)return;
      const existing=Object.values(nyachoMembers).find(item=>item.name.toLowerCase()===String(member.name).toLowerCase());
      if(existing)return;
      const name=String(member.name),soopId=String(member.soopId||'');newMembers.push({name,type:member.type||'member',soopId,img:String(member.img||memberImage(name,soopId))});
    });
    data.groups.forEach(group=>{if(group?.name&&Array.isArray(group.members)&&!nyachoMemberGroups[group.name])nyachoMemberGroups[group.name]={name:group.name,members:group.members}});
    if(newMembers.length)await upsertSharedMembers(newMembers);saveMemberGroups();await loadSharedMembers();renderMemberTabs();renderMembers();
  }catch(error){alert(error.message||'멤버 데이터 JSON 형식이 올바르지 않습니다.')}
}

